# รอบ 231 (LICENSE_USAGE_OVERAGE_AUDIT §B.3–B.6 · §D.1 · คำตัดสินข้อ 231-1..7): ด่านส่วนเกินตัวเดียว (IOverageService.DecideAsync ← OveragePolicy.Decide) ที่ 4 จุดเขียน + งานพื้นที่ ·
# มิเตอร์ → ใบ (UsageInvoicingJob ผ่าน Helpers/UsageInvoiceLines) → ขั้น 1 ล็อกสิทธิ์ส่วนเกิน (dunning) · snapshot ก่อนล้างตัวนับทุกจุดขึ้นเดือน · ผู้อ่าน OverageAutoChargeSavedCard
_R231OV_WHY = "รอบ 231 ส่วนเกินโควตา: "
_OVSVC = "Services/Implementations/OverageService.cs"
RULES += [
    dict(file=_OVSVC, method="DecideAsync",
         must=["GetPolicyViewAsync(", "RateForAsync(", "OveragePolicy.Decide(resourceKey, adding, policy, rate, spent, now)", "NotifyCappedOnceAsync("],
         before=[("OveragePolicy.Decide(", "NotifyCappedOnceAsync(")],
         why=_R231OV_WHY + "ด่านตัวเดียว = นโยบาย + ราคาที่มีผล + ยอดที่คิดแล้ว ⇒ OveragePolicy.Decide (pure) · ถึงเพดาน/ไม่มีราคาแจ้ง overage.capped ครั้งเดียวต่อเดือน"),
    dict(file=_OVSVC, method="RecordAsync",
         must=["_metering.RecordAsync(", "OverageResources.FeatureCode(resourceKey)", "UnitPriceOverride: price", "OccurredAtOverride: occurredAtUtc",
               "StampPeriodOnceAsync(", "NotifyOverageStartedAsync(", "NotifyFreeOverageAsync("],
         must_lit=['"StartedNotifiedPeriod"', '"FreeOverageNotifiedPeriod"'],
         forbid=["AddOnCodes.DocumentsOverage,", "spentBefore"],
         why=_R231OV_WHY + "มิเตอร์ส่วนเกิน = UsageEvent เดิม (idempotent) รหัส overage.* ราคา snapshot · เริ่มคิดครั้งแรกของเดือน/ออกใบฟรีเกินโควตา แจ้งครั้งเดียวต่อเดือนด้วยตราประทับ (N2/S8) ไม่เดาจากยอด"),
    dict(file=_OVSVC, method="SetPolicyAsync",
         must=["OveragePolicy.ValidateTenantUpdate(", "LockedByUnpaidAt != null && req.Mode == OverageMode.AllowOverage && row.Mode != OverageMode.AllowOverage", "RateForAsync(",
               "CapRaised(row.MonthlyCapAmount, req.MonthlyCapAmount)", "Audit(companyId, actor, RulePolicy"],
         before=[("OveragePolicy.ValidateTenantUpdate(", "_db.CompanyOveragePolicies.Add("), ("Audit(companyId, actor, RulePolicy", "_db.SaveChangesAsync(")],
         why=_R231OV_WHY + "ผู้เช่าเปิดต้องยอมรับฉบับ · ถูกล็อกเพราะค้างเปิดเองไม่ได้ · ไม่มีราคาเปิดไม่ได้ · audit chain ก่อนบันทึก"),
    dict(file=_OVSVC, method="ApplyUnpaidLockAsync",
         must=["OveragePolicy.UnpaidLock(openUsageInvoices, DateTime.UtcNow", "row.LockedByUnpaidAt = DateTime.UtcNow", "Audit(companyId, null"],
         why=_R231OV_WHY + "ขั้น 1 ค้างชำระตัดสินด้วย pure helper (ล็อกเมื่อเกินวันครบกำหนด — N1) · ล็อก/ปลดลง audit"),
    dict(file=_OVSVC, method="UpsertRateAsync",
         must=["OverageResources.IsKnown(resourceKey)", "OveragePolicy.ValidateRate(resourceKey, unitSize)", "r.EffectiveToUtc = now", "_db.AddChainedAuditLog("], must_lit=["ต้องระบุเหตุผล"],
         before=[("r.EffectiveToUtc = now", "_db.OverageRates.Add("), ("_db.AddChainedAuditLog(", "_db.SaveChangesAsync(")],
         why=_R231OV_WHY + "ราคา: closed list · ปิดแถวเดิมก่อนเพิ่มแถวใหม่ (ไม่แก้ทับ) · เหตุผล + audit"),
    dict(file=DOC, method="CreateDocumentAsync",
         must=["DocumentQuotaPolicy.CanRefuseWhenOverQuota(quotaClass)", "DecideDocumentOverageAsync(companyId)", "RecordDocumentOverageAsync(companyId, doc, quotaClass)"],
         must_re=[r"CanRefuseWhenOverQuota\(quotaClass\)\s*&&\s*!\(await\s+DecideDocumentOverageAsync\(companyId\)\)\.Allowed"],
         why=_R231OV_WHY + "ใบที่รอได้เกินโควตาถามด่านส่วนเกินก่อน 409 · ทุกฉบับเกินโควตาเข้ามิเตอร์ (คิดเงินเฉพาะเมื่อด่านอนุญาต)"),
    dict(file=DOC, method="ApproveDocumentAsync#2",   # ตัวที่ทำงานจริง (2 ตัวแรกเป็น overload แบบ expression-bodied)
         must=["doc.QuotaCountDeferred", "DecideDocumentOverageAsync(companyId)", "RecordDocumentOverageAsync(companyId, doc,"],
         why=_R231OV_WHY + "ทางเข้าอนุมัติใบที่เลื่อนนับเดินด่านส่วนเกินเดียวกับตอนสร้าง"),
    dict(file=DOC, method="RecordDocumentOverageAsync",
         must=["DecideDocumentOverageAsync(companyId)", "_overage.RecordAsync(companyId, Models.Constants.OverageResources.Documents, 1", "chargeable: decision.Allowed"],
         why=_R231OV_WHY + "เอกสารเกินโควตา: คิดเงินเฉพาะเมื่อด่านอนุญาต · ใบกฎหมายบังคับโหมดล็อก = ราคา 0 (ห้ามคิดเงินที่ผู้เช่าไม่ได้ตกลง)"),
    dict(file="Services/Implementations/OcrQuotaService.cs", method="TryConsumeAsync",
         must=["UsageSnapshotService.WriteRolloverAsync(_db, sub, DateTime.UtcNow)", "SubscriptionUsageRollover.RollIfDue(sub, DateTime.UtcNow)",
               "_overage.DecideAsync(companyId, Accounting.Models.Constants.OverageResources.OcrPages, 1)", "sub.CurrentMonthOcrPages++", "_overage!.RecordAsync("],
         before=[("UsageSnapshotService.WriteRolloverAsync(_db, sub, DateTime.UtcNow)", "SubscriptionUsageRollover.RollIfDue(sub, DateTime.UtcNow)"),
                 ("_overage.DecideAsync(companyId, Accounting.Models.Constants.OverageResources.OcrPages, 1)", "_overage!.RecordAsync(")],
         why=_R231OV_WHY + "OCR: snapshot ก่อนล้างตัวนับ · เครดิตหมด ⇒ ถามด่านก่อนสแกนต่อ ⇒ มิเตอร์ต่อหน้าหลัง commit"),
    dict(file="Services/Implementations/OcrQuotaService.cs", method="ResetMonthlyUsageAsync",
         must=["UsageSnapshotService.WriteRolloverAsync(_db, sub, now)"],
         before=[("UsageSnapshotService.WriteRolloverAsync(_db, sub, now)", "SubscriptionUsageRollover.RollIfDue(sub, now)")],
         why=_R231OV_WHY + "งานล้างรายเดือนก็ snapshot ก่อนล้าง (ไม่ snapshot = ไม่ล้าง)"),
    dict(file="Services/Implementations/SubscriptionService.cs", method="CheckUsageLimitAsync",
         must=["UsageSnapshotService.WriteRolloverAsync(_db, sub, DateTime.UtcNow)"],
         before=[("UsageSnapshotService.WriteRolloverAsync(_db, sub, DateTime.UtcNow)", "SubscriptionUsageRollover.RollIfDue(")],
         why=_R231OV_WHY + "จุดขึ้นเดือนของเอกสาร snapshot ก่อนล้าง"),
    dict(file="Services/Implementations/SubscriptionService.cs", method="CanFitStorageAsync",
         must=["GetStorageStatusAsync(companyId)", "_overage.DecideAsync(companyId, Models.Constants.OverageResources.StorageGb"],
         why=_R231OV_WHY + "สื่อ CMS เกินเพดาน: เปิดส่วนเกินพื้นที่ ⇒ ผ่าน (คิด GB-เดือนสิ้นเดือน) · ไม่งั้นบล็อกเดิม"),
    dict(file="Services/Implementations/NotifyQuotaService.cs", method="TryReserveOverageAsync",
         must=["_overage.DecideAsync(companyId, AddOnCodesOverageResource, 1, ct)", "_overage.RecordAsync(companyId, AddOnCodesOverageResource, 1, OverageKey(period, used, counter)", "chargeable: true"],
         before=[("_overage.DecideAsync(companyId, AddOnCodesOverageResource, 1, ct)", "_overage.RecordAsync(")],
         why=_R231OV_WHY + "ข้อความช่องกลางเต็ม: ถามด่านก่อนนับต่อ ⇒ มิเตอร์ต่อข้อความ (คีย์ = ตัวนับหลังเพิ่ม)"),
    dict(file="Services/Implementations/NotifyQuotaService.cs", method="ReleaseAsync",
         must=["reservation.Kind == KindOverage", "OverageKey(reservation.Period, reservation.UsedAfter, counter)"], must_lit=['"BilledPeriod" IS NULL'],
         why=_R231OV_WHY + "ส่งล้ม ⇒ ถอน UsageEvent ส่วนเกินของข้อความนั้น (เฉพาะที่ยังไม่ออกบิล) — ไม่คิดเงินข้อความที่ไม่ได้ส่ง"),
    dict(file="Services/Implementations/UsageSnapshotService.cs", method="SettleStorageOverageAsync#1",   # ตัว static ที่ทำงานจริง (ตัวแรกเป็น wrapper expression-bodied)
         must=["OveragePolicy.StorageOverageGbMonth(", "DateTime.DaysInMonth(y, m)", "overage.SpentInPeriodAsync(companyId, period, ct)", "chargeable: chargeable", "occurredAtUtc: end.AddSeconds(-1)"],
         forbid=["overage.DecideAsync(", "GetPolicyViewAsync(companyId, ct)).Mode"],
         why=_R231OV_WHY + "ฝ่ายค้าน B2/S4/S5: พื้นที่ GB-เดือนคิดจากตัวอย่างรายวัน (ราคา snapshot ต่อวัน · หารวันในเดือน) ไม่ถามโหมด/ล็อกตอนปิดงวด · เพดานตรวจกับยอดงวดนั้น · OccurredAt = ท้ายงวด"),
    dict(file="Services/Implementations/UsageSnapshotService.cs", method="WriteDailyAsync",
         must=["_overage.RateForAsync(companyId, OverageResources.StorageGb, ct)", "UpsertDailyStorageAsync(_db, companyId", "!policy.IsLocked"],
         why=_R231OV_WHY + "ฝ่ายค้าน B2: ตัวอย่างพื้นที่เก็บเฉพาะวันที่เปิด+ไม่ล็อก+มีราคา พร้อม snapshot ราคา"),
    dict(file="Services/Background/PlatformDunningJob.cs", method="DueCompaniesAsync",
         must=["OverageService.LockedOverageCompaniesAsync(db, ct)", ".Union(lockedOverage)"],
         why=_R231OV_WHY + "ฝ่ายค้าน B1: บริษัทที่ถูกล็อกส่วนเกินถูกประเมินต่อจนปลด (ไม่มีใบค้างแล้วก็ยังต้องประเมิน)"),
    dict(file="Services/Implementations/SubscriptionService.cs", method="NotifyDocumentQuotaCrossedAsync",
         must=["OverageService.BillingRecipientsAsync(_db, companyId"],
         forbid=["cu.Role == UserRole.Owner"],
         why=_R231OV_WHY + "ฝ่ายค้าน S7: ผู้รับแจ้งโควตาเอกสาร = เจ้าของ + BillingManage ผ่านตัวเดียว"),
    dict(file="Services/Implementations/NotifyQuotaService.cs", method="AlertIfCrossedAsync",
         must=["OverageService.BillingRecipientsAsync(db, companyId, ct)"],
         forbid=["cu.Role == UserRole.Owner"],
         why=_R231OV_WHY + "ฝ่ายค้าน S7: ผู้รับแจ้งโควตาข้อความ = เจ้าของ + BillingManage ผ่านตัวเดียว"),
    dict(file="Services/Implementations/UsageSnapshotService.cs", method="WarnIfDueAsync",
         must=["QuotaWarnPolicy.DueAfterWarned(used, limit, warned, percents)", "OverageService.BillingRecipientsAsync(_db, companyId, ct)"], must_lit=['"WarnedPercent" < {3}'],
         before=[("QuotaWarnPolicy.DueAfterWarned(", "_notify.DispatchAsync(")],
         why=_R231OV_WHY + "เตือนใกล้เต็มตามเกณฑ์ของแอดมิน ครั้งเดียวต่อเกณฑ์ต่อเดือน (ประทับก่อนส่ง) · ผู้รับ = เจ้าของ + BillingManage"),
    dict(file="Services/Background/UsageInvoicingJob.cs", method="RunOnce",
         must=["PlatformBillingSettingsService.LoadPolicyAsync(db, ct)", "pending.GroupBy(u => u.CompanyId)", "Accounting.Helpers.UsageInvoiceLines.Dispose(", "Accounting.Helpers.UsageInvoiceLines.Build(",
               "Accounting.Helpers.UsageInvoiceLines.DueDate(issueDate, billingPolicy.OverageGraceDays)", "Accounting.Helpers.UsageInvoiceLines.Reference(group.Key, latestPeriod)", "r.BilledPeriod = periodOf[r.Id]"],
         forbid=["issueDate.AddDays(7)", "new PlatformInvoiceLine(", "Period = AddOnBilling.PeriodOf(u.OccurredAt) }"],
         why=_R231OV_WHY + "ใบค่าใช้งาน: ขั้นต่ำ/ครบกำหนดจากค่าตั้งแอดมิน · บรรทัด (§86/4) ประกอบด้วย helper เดียว ห้ามประกอบเอง"),
    dict(file="Services/Implementations/PlatformDunningService.cs", method="EvaluateCompanyAsync",
         must=["_overage.ApplyUnpaidLockAsync(companyId, usageInvoices, policy.OverageGraceDays", "OveragePolicy.ForSuspension(invoices, references, policy.OverageUnpaidAction)",
               "PlatformDunningPolicy.Decide(now, forSuspension"],
         before=[("_overage.ApplyUnpaidLockAsync(", "PlatformDunningPolicy.Decide(now, forSuspension")],
         why=_R231OV_WHY + "ขั้น 1 ล็อกสิทธิ์ส่วนเกินก่อนตัดสินขั้น 2 · LockOverageOnly ตัดใบ USAGE- ออกจากการระงับ"),
    dict(file="Services/Payments/PlatformAutoChargeService.cs", method="ProcessPayerAsync",
         must=["PlatformAutoChargePolicy.AutoChargeAllowedForKind(PlatformInvoiceRules.KindOf(r.Reference), overageAutoChargeSavedCard)"],
         before=[("PlatformAutoChargePolicy.Decide(", "PlatformAutoChargePolicy.AutoChargeAllowedForKind("), ("PlatformAutoChargePolicy.AutoChargeAllowedForKind(", "ChargeInvoiceAsync(")],
         why=_R231OV_WHY + "ค่าตั้ง OverageAutoChargeSavedCard มีผู้อ่านจริง — ใบ USAGE- ไม่เข้าคิวตัดบัตรเมื่อปิด"),
]

# ── รอบ 232 (บั๊กเจ้าของ): หน้ารวมใบสั่งซื้อ "◐ ออกใบแจ้งหนี้ซื้อ PI-… แล้ว · ไม่ทราบสัดส่วน" ทั้งที่ยอดเท่าเป๊ะ — ป้ายอ่าน SourceLineId ของบรรทัดใบลูกเท่านั้น
#    ⇒ ทุกทางเข้าที่สร้าง/เขียนบรรทัดต้องประทับ/ย้าย SourceLineId ผ่านตัวตัดสินเดียว Helpers/SourceLineBackfill (เทสต์ SourceLineBackfillTests ล็อกแค่ helper) ──
_R232SL_WHY = "รอบ 232: บรรทัดใบลูกต้องชี้บรรทัดต้นทาง (SourceLineId) ทุกทางเข้า ไม่งั้นป้าย lifecycle ของใบต้นทาง \"ไม่ทราบสัดส่วน\" + ด่านกันแปลงเกินมองไม่เห็นใบลูก — "
RULES += [
    dict(file=DOC, method="CreateDocumentAsync", must=["StampSourceLinesFromRelatedAsync("],
         why=_R232SL_WHY + "สร้างใบมือ/API โดยเลือกใบต้นทางบนฟอร์ม (RelatedDocumentId) ต้องประทับเมื่อจับคู่แน่นอน"),
    dict(file=DOC, method="StampSourceLinesFromRelatedAsync",
         must=["SourceLineBackfill.Stamp(", "DocumentConversionProgress.IsConversionBearing("],
         must_re=[r"matchQuantity:\s*true", r"doc\.IsDeposit\s*\|\|\s*doc\.ReplacesDocumentId\.HasValue"],
         why=_R232SL_WHY + "ประทับเฉพาะใบต้นทางชนิดแปลงต่อ · จำนวนต้องตรง (ห้ามเดา) · ใบมัดจำ/ใบออกแทนไม่แตะ (กติกาเดียวกับ DocumentLinkPolicy.ChildBlockReason)"),
    dict(file=DOC, method="UpdateDocumentAsync", must=["RelinkSourceLinesAfterLineRewriteAsync("],
         before=[("_db.DocumentLines.RemoveRange(doc.Lines)", "RelinkSourceLinesAfterLineRewriteAsync(")],
         why=_R232SL_WHY + "แก้ไขใบแล้วบรรทัดถูกสร้างใหม่ (Id ใหม่) — ตัวชี้ของใบลูกต้องย้ายตาม + ค่าเดิมของใบลูกต้องไม่หายเมื่อผู้เรียกไม่ส่ง sourceLineId"),
    dict(file=DOC, method="RelinkSourceLinesAfterLineRewriteAsync",
         must=["SourceLineBackfill.CarryFromPrevious(", "SourceLineBackfill.Remap("],
         must_re=[r"l\.Document\.CompanyId\s*==\s*companyId"],
         why=_R232SL_WHY + "ย้ายตัวชี้ (Remap) + ยกค่าเดิม (CarryFromPrevious) · query ผู้พึ่งพากรองบริษัท (กฎ M)"),
    dict(file=DOC, method="LoadConversionSummariesAsync",
         must=["LoadBilledViaDeliveryAsync(", "DocumentConversionProgress.EvaluateByValue("],
         why=_R232SL_WHY + "สาย PO → GRN → PI / QT → DN → INV: ป้ายของใบต้นทางต้องมองทะลุใบส่งของ/ใบรับสินค้าด้วยตัวโหลดเดียวกับด่านกันแปลงเกิน"),
    # รอบ 242 (ข้อ 242-B · เจ้าของ 2026-11-06 PO-20260930-0002 → PI-20261001-0005): ข้อเท็จจริงใบลูกผูกหัวใบ (ยอดฐาน + ใบมัดจำ) ต้องถึงตัวตัดสิน
    # ไม่งั้นกติกา "ใบลูกใบเดียว ยอดเท่ากันทั้งใบ ⇒ ครบ" ไม่มีวันทำงาน (ป้าย "ไม่ทราบสัดส่วน" กลับมา) · ยอดใบลูกกรองบริษัท
    dict(file=DOC, method="LoadConversionSummariesAsync",
         must=["DocumentConversionProgress.HeaderLinkedChild("],
         call_args=[("DocumentConversionProgress.EvaluateByValue(", "headerLinked")],
         must_re=[r"headerChildIds\.Contains\(l\.DocumentId\)\s*&&\s*l\.Document\.CompanyId\s*==\s*companyId"],
         why="รอบ 242 ข้อ 242-B: ใบลูกใบเดียวยอดเท่ากันทั้งใบ ⇒ ครบ — ตัวตัดสินเดียว DocumentConversionProgress.SoleChildMatchesTotal"),
    dict(file=OCR, method="BuildScanLinesAsync", must=["SourceLineBackfill.Stamp("],
         must_re=[r"if\s*\(\s*linkedPo\s*!=\s*null\s*\)"],
         why=_R232SL_WHY + "สแกนที่ผูกใบสั่งซื้อ (/link-po) แต่ไม่ได้จับคู่รายบรรทัด ต้องประทับเมื่อจับคู่แน่นอน"),
    dict(file="Services/Background/SourceLineBackfillJob.cs", method="RunCompanyAsync",
         must=["SourceLineBackfill.Stamp(", "db.AddChainedAuditLog(", "DocumentConversionProgress.SourceTypes", "DocumentConversionProgress.InactiveChildStatuses",
               "company.SourceLineBackfillCheckedAt = nowUtc"],
         must_re=[r"overwriteForeign:\s*true", r"matchQuantity:\s*true", r"c\.CompanyId\s*==\s*companyId\s*&&\s*s\.CompanyId\s*==\s*companyId",
                  r"touched\s*>\s*cursor", r"s\.UpdatedAt\s*!=\s*null", r"c\.UpdatedAt\s*!=\s*null"],
         before=[("SourceLineBackfill.Stamp(", "company.SourceLineBackfillCheckedAt = nowUtc")],
         why=_R232SL_WHY + "งานซ่อมข้อมูลเก่า: กติกาเดียวกับทางเข้าสด · ทับได้เฉพาะ dangling · audit chain · ใบลูก-ต้นทางบริษัทเดียวกัน · watermark ต่อบริษัท (S4) เลื่อนหลังวน batch จนหมด"),
    dict(file=OCR, method="BuildScanLinesAsync", must=["OcrSourceLineNote.Stamped(", "OcrSourceLineNote.Unmatched("],
         why=_R232SL_WHY + "S5 ผลจับคู่ต้องบอกคน (แท็ก [SRC-LINE] → DTO SourceLinesStamped/SourceLineWarning) ไม่ใช่เงียบ"),
]

# ── รอบ 232 (คำตัดสิน 232-Checkout-2): หน้าซื้อแพ็กเกจสาธารณะ — ยอดจากเซิร์ฟเวอร์ · สวิตช์แอดมิน · ด่านโหมดทดสอบ · หลักฐานยอมรับนโยบาย ──
_R232_CHECKOUT = "Services/Platform/PublicCheckoutService.cs"
_R232_CTRL = "Controllers/PublicCheckoutController.cs"
_R232_WHY = "232-Checkout-2: "
RULES += [
    dict(file=_R232_CHECKOUT, method="AvailabilityAsync",
         must=["PublicCheckoutPolicy.Decide(", "PublicCheckoutEnabled", "PlatformLiveConfirmedAt"],
         why=_R232_WHY + "สวิตช์แอดมิน + โหมดช่องทาง + ด่าน live ของแพลตฟอร์ม ตัดสินที่ PublicCheckoutPolicy ตัวเดียว (ห้ามประกอบเอง)"),
    # ฝ่ายค้าน B1: ชนิดคำสั่งซื้อตัดสินก่อนเรียก service ที่มี side-effect (เดิม Active+เดิม ⇒ throw · ดาวน์เกรด ⇒ ScheduledPlan ถูกบันทึกแล้วจึง throw)
    dict(file=_R232_CHECKOUT, method="CreateOrderAsync",
         must=["AvailabilityAsync(", "RequireOwnerAsync(", "PublicCheckoutPolicy.CanResume(", "DecideOrderAsync(", "_subs.ConvertTrialAsync(",
               "_subs.RequestRenewalPaymentAsync(", "PublicCheckoutPolicy.OrderKind.Refused", "PublicCheckoutPolicy.OrderKind.Renewal"],
         before=[("AvailabilityAsync(", "_subs.ConvertTrialAsync("), ("RequireOwnerAsync(", "_subs.ConvertTrialAsync("),
                 ("PublicCheckoutPolicy.CanResume(", "_subs.ConvertTrialAsync("),
                 ("DecideOrderAsync(", "_subs.ConvertTrialAsync("), ("DecideOrderAsync(", "_subs.RequestRenewalPaymentAsync("),
                 ("PublicCheckoutPolicy.OrderKind.Refused", "_subs.RequestRenewalPaymentAsync("), ("PublicCheckoutPolicy.OrderKind.Refused", "_subs.ConvertTrialAsync(")],
         forbid=["PlatformPlanPricing.CyclePrice(", "PlatformPlanPricing.AmountDue(", "new SubscriptionPayment", "_subs.ChangeSubscriptionAsync("],
         why=_R232_WHY + "B1 ชนิดคำสั่งซื้อ (ซื้อใหม่/ต่ออายุ/อัปเกรด/ปฏิเสธ) ตัดสินก่อนมี side-effect · ซื้อใหม่/อัปเกรดผ่าน ConvertTrialAsync · ต่ออายุผ่าน SubmitPaymentAsync (เซิร์ฟเวอร์ตรวจยอดซ้ำ) — ไม่คิดเงินเอง"),
    dict(file=_R232_CHECKOUT, method="DecideOrderAsync",
         must=["PublicCheckoutPolicy.DecideOrder(", "_subs.QuotePlanChangeAsync(", "PlatformPriceOverrideStore.AmountDueAsync(", "currentPlan: sub.Plan",
               "PlatformPlanPricing.ScheduleBlockedByIssuedRenewal("],
         forbid=["_subs.ConvertTrialAsync(", "_subs.ChangeSubscriptionAsync(", "_subs.SubmitPaymentAsync(", "_subs.RequestRenewalPaymentAsync(", "SaveChangesAsync("],
         why=_R232_WHY + "B1 ตัวตัดสินชนิดคำสั่งซื้ออ่านอย่างเดียว (ไม่มี side-effect) · ราคาต่ออายุจากตัวตัดสินเดียว (IsRenewalPurchase ผ่าน currentPlan)"),
    dict(file=_R232_CHECKOUT, method="QuoteAsync",
         must=["DecideOrderAsync(", "q!.CouponProblem", "OrderKind.Refused", "OrderKind.Renewal"],
         before=[("DecideOrderAsync(", "q!.CouponProblem")],
         why=_R232_WHY + "B1 ยอดตะกร้าของบริษัทใช้ตัวตัดสินชนิดเดียวกับตอนยืนยัน (ดาวน์เกรดบอกตั้งแต่ตะกร้า · ต่ออายุแสดงราคาต่ออายุ)"),
    # ฝ่ายค้าน S1: เส้นเริ่มชำระเดียวทั้ง Live/Test — ห้ามสำเนาด่าน (เดิม Test สร้าง intent เองด้วยด่านชุดย่อย ⇒ ขาด price-drift/PlatformDoublePayment)
    dict(file=_R232_CHECKOUT, method="StartIntentAsync",
         must=["AvailabilityAsync(", "_platform.StartSubscriptionPaymentAsync(", "allowTestMode: avail.IsTestMode"],
         must_re=[r"if\s*\(\s*!\s*avail\.OnlineAvailable\s*\)\s*throw"],
         before=[("AvailabilityAsync(", "_platform.StartSubscriptionPaymentAsync(")],
         forbid=["PlatformPlanPricing.CyclePrice(", "PlatformPlanPricing.AmountDue(", "_intents.", "StartPaymentRequest(", "status.Methods.Contains(",
                 "allowTestMode: true"],
         why=_R232_WHY + "S1 Live/Test เส้นเดียว IPlatformPaymentService.StartSubscriptionPaymentAsync (ด่านเดิมครบ) · โหมดทดสอบผ่านได้เฉพาะเมื่อหน้านี้ตัดสินว่าเป็นโหมดทดสอบ"),
    dict(file="Services/Payments/PlatformPaymentService.cs", method="StartAsync",
         must=["allowTestMode: false"], forbid=["allowTestMode: true"],
         why=_R232_WHY + "S1 ผู้เรียก StartAsync เดิมทุกตัว (ส่วนเสริม/โควตา/ใบแจ้งหนี้) ไม่มีทางผ่านโหมดทดสอบ"),
    dict(file="Services/Payments/PlatformPaymentService.cs", method="StartSubscriptionPaymentAsync",
         must=["StartCoreAsync(", "allowTestMode)"],
         why=_R232_WHY + "S1 ค่า allowTestMode ส่งต่อถึงด่านช่องทางตัวเดียว (StartRefusal) — ด่านยอด/สลิป/พักเหมือนเดิม"),
    # ทิศตรงข้าม S1: ผู้เรียกเดิมห้ามขอโหมดทดสอบ (ไม่ส่ง = false = โหมดทดสอบถูกปฏิเสธ)
    dict(file="Controllers/PlatformPaymentController.cs", method="StartSubscription", must=["StartSubscriptionPaymentAsync("], forbid=["allowTestMode"],
         why=_R232_WHY + "S1 ศูนย์บิล (ผู้เช่าในระบบ) ไม่ผ่านโหมดทดสอบ"),
    dict(file="Controllers/PlatformPayLinkController.cs", method="PayOnline", must=["StartSubscriptionPaymentAsync("], forbid=["allowTestMode"],
         why=_R232_WHY + "S1 ลิงก์ชำระไม่ผ่านโหมดทดสอบ"),
    dict(file="Services/Payments/PlatformAutoChargeService.cs", method="ChargeInvoiceAsync", must=["StartSubscriptionPaymentAsync("], forbid=["allowTestMode"],
         why=_R232_WHY + "S1 ตัดบัตรอัตโนมัติไม่ผ่านโหมดทดสอบ"),
    dict(file=_R232_CHECKOUT, method="OrderStatusAsync",
         must=["PublicCheckoutPolicy.Resolve(", "PaymentIntentTestMode.Decide(", "PublicCheckoutPolicy.OutcomeMessage("],
         forbid=["Outcome.Activated;"],
         why=_R232_WHY + "ผลลัพธ์หน้าสำเร็จ (เปิดสิทธิ์/รอตรวจ/ทดสอบ/ยังไม่จ่าย) ตัดสินที่ PublicCheckoutPolicy.Resolve — เงินทดสอบ ≠ เปิดสิทธิ์"),
    dict(file=_R232_CTRL, method="CreateOrder",
         must=["OwnerDenyAsync(", "RateOkAsync(", "PurchasePolicyAcceptance.Problem(", "PurchasePolicyAcceptance.EnforcePlatformForUserAsync(",
               "_checkout.CreateOrderAsync("],
         before=[("PurchasePolicyAcceptance.Problem(", "_checkout.CreateOrderAsync("), ("RateOkAsync(", "_checkout.CreateOrderAsync("),
                 ("_checkout.CreateOrderAsync(", "PurchasePolicyAcceptance.EnforcePlatformForUserAsync(")],
         why=_R232_WHY + "เจ้าของบริษัท + โควตา + ติ๊กยอมรับนโยบาย (ตรวจก่อนสร้าง · หลักฐานผูกรายการหลังสร้าง)"),
    # ฝ่ายค้าน S5: หลักฐานยอมรับไม่ซ้ำทุกคลิก · S3: คูปองนับรหัสต่างกันต่อผู้ใช้ก่อนประเมิน
    dict(file=_R232_CTRL, method="CreateOrder",
         must=["PurchasePolicyAcceptance.UserAlreadyAcceptedAsync(", "accepted: !alreadyAccepted", "CouponAttemptOkAsync("],
         before=[("CouponAttemptOkAsync(", "_checkout.CreateOrderAsync("),
                 ("PurchasePolicyAcceptance.UserAlreadyAcceptedAsync(", "PurchasePolicyAcceptance.EnforcePlatformForUserAsync(")],
         why=_R232_WHY + "S5 resume/กดซ้ำไม่เพิ่มแถวหลักฐาน · S3 รหัสคูปองต่างกันต่อ 10 นาทีต่อผู้ใช้"),
    dict(file=_R232_CTRL, method="CompanyQuote",
         must=["OwnerDenyAsync(", "UserQuoteRateOkAsync(", "CouponAttemptOkAsync(", "_checkout.QuoteAsync("],
         before=[("UserQuoteRateOkAsync(", "_checkout.QuoteAsync("), ("CouponAttemptOkAsync(", "_checkout.QuoteAsync(")],
         why=_R232_WHY + "S3 คูปองไล่เดาได้ — โควตาต่อผู้ใช้ + รหัสต่างกันต่อ 10 นาที ตรวจก่อนประเมิน (ไม่งั้น 200/429 เป็นตัวบอกรหัสถูก)"),
    dict(file=_R232_CTRL, method="CouponAttemptOkAsync",
         must=["PublicCheckoutPolicy.CouponWindowId(", "PublicCheckoutPolicy.CouponCodesPerWindowPerUser", "failClosed: true"],
         why=_R232_WHY + "S3 ตัวนับบน PostgreSQL (multi-instance) · ค่าคงที่จาก PublicCheckoutPolicy ตัวเดียว"),
    # ฝ่ายค้าน N3: เติม/แก้อังกฤษของฉบับที่เผยแพร่แล้ว — เลขฉบับคงเดิม · audit chain
    dict(file="Services/Implementations/LegalDocumentService.cs", method="SetPublishedEnglishAsync",
         must=["LegalDocumentLanguage.PublishedEnglishRefusal(", "AddChainedAuditLog(", "row.BodyMarkdownEn = after"],
         before=[("LegalDocumentLanguage.PublishedEnglishRefusal(", "row.BodyMarkdownEn = after")],
         forbid=["row.Version =", "row.EffectiveDate =", "row.BodyMarkdown =", "row.Status ="],
         why="232-Checkout-1 (ฝ่ายค้าน N3): อังกฤษเป็นคำแปลประกอบ — แก้ได้โดยไม่ขยับเลขฉบับ/เนื้อไทย/สถานะ · ทุกการเปลี่ยนลง audit chain"),
    dict(file=_R232_CTRL, method="StartIntent",
         must=["OwnerDenyAsync(", "RateOkAsync(", "PurchasePolicyAcceptance.EnforcePlatformForUserAsync(", "_checkout.StartIntentAsync(",
               "PurchasePolicyAcceptance.UserAlreadyAcceptedAsync("],
         before=[("PurchasePolicyAcceptance.EnforcePlatformForUserAsync(", "_checkout.StartIntentAsync("),
                 ("PurchasePolicyAcceptance.UserAlreadyAcceptedAsync(", "PurchasePolicyAcceptance.EnforcePlatformForUserAsync(")],
         forbid=["req.Amount", "amount:"],
         why=_R232_WHY + "เริ่มชำระ: ยอดไม่รับจากหน้าเว็บ · หลักฐานยอมรับก่อนเริ่ม"),
    # ═════════ รอบ 233 (คำตัดสิน 233-* · LICENSE_CASE_MATRIX) — "สิ่งที่จะได้ถ้าจ่ายเงินนี้" ตัวเดียว: ทุกทางเข้าเรียก PlanPurchasePreview · วันที่ตัวคำนวณเดียว ═════════
    dict(file=_SUBSVC, method="QuotePlanChangeAsync",
         must=["QuotePlanChangeCoreAsync(", "PlanPreviewForQuoteAsync("],
         before=[("QuotePlanChangeCoreAsync(", "PlanPreviewForQuoteAsync(")],
         why=_R233_WHY + "hub ผู้เช่า (billing.html) ได้ preview ทุกใบเสนอ"),
    dict(file=_SUBSVC, method="PlanPreviewForQuoteAsync",
         must=["PlanPurchasePreview.ForSame(", "PlanPurchasePreview.ForScheduled(", "PlanPurchasePreview.ForPurchase(", "OldPriceBasis: q.OldPriceBasis",
               "PlanPurchasePreview.CurrentOf(", "PlanPurchasePreview.TargetOf("],
         forbid=[".AddMonths(", "AddDays(", "PlatformPlanPricing.PeriodStart("],
         why=_R233_WHY + "preview ห้ามคำนวณวันที่/เครดิตเอง — วันที่จาก PaidPeriod ใน PlanPurchasePreview เท่านั้น"),
    dict(file=_SUBSVC, method="ReviewPaymentLockedAsync",
         must=["PlanPurchasePreview.PaidPeriod(changeKind, sub.Plan == payment.RequestedPlan, sub.IsPermanentFree, wasTrial",
               "isProration: false, isCycleChange: true", "isProration: true, isCycleChange: false", "payment.PaymentDate = paidAt"],
         before=[("var paidAt = PlatformPlanPricing.ApprovedPaymentDate(", "PlanPurchasePreview.PaidPeriod(changeKind")],
         forbid=["PlatformPlanPricing.PeriodStart(", "baseDate.AddMonths(", "payment.PaymentDate.AddMonths(", "sub.EndDate = keepEnd",
                 "acct.EndDate > now ? acct.EndDate : now", "acctBase.AddMonths("],
         why=_R233_WHY + "วันที่ที่ประทับตอนอนุมัติ = วันที่ที่ preview บอก (ตัวคำนวณเดียว · วันชำระ = ApprovedPaymentDate)"),
    # ฝ่ายค้าน 233 S1/B1/B2/K-3: PaidPeriod ของเส้นซื้อ/ต่ออายุต้องรับวันรับเงิน (paidAt — ใส่ `now` กลับ = ฟ้อง) + เวลาอนุมัติ (กันรอบที่จบก่อนอนุมัติ) ·
    # ApplyTemplate รับวันหมดอายุของรอบที่จ่าย (ไม่ปิดรอบด้วย UtcNow ทับ) · แพลนบัญชีใช้ PaidPeriod/paidAt เดียวกัน
    dict(file=_SUBSVC, method="ReviewPaymentLockedAsync",
         call_args=[("PlanPurchasePreview.PaidPeriod(changeKind", "paidAt"), ("PlanPurchasePreview.PaidPeriod(changeKind", "approvedAtUtc"),
                    ("PlanPurchasePreview.PaidPeriod(PlatformPlanPricing.ChangeKind.Same, true", "paidAt"),
                    ("PlanPurchasePreview.PaidPeriod(PlatformPlanPricing.ChangeKind.Same, false", "approvedAtUtc")],
         must=["paidPeriodEndUtc: newEndDate", "paidPeriodEndUtc: ccPeriod.EndUtc", "period.StartedAtApproval", "ccPeriod.StartedAtApproval"],
         must_lit=["{PlanPurchasePreview.BackdatedNote}"],
         why=_R233_WHY + "ฝ่ายค้าน B1/B2/S1/K-3: วันรับเงินจริง · รอบที่ใช้ได้จริงเสมอ · ApplyTemplate ไม่ทับวันหมดอายุ · แพลนบัญชีตรงกับ subscription"),
    dict(file=_SUBSVC, method="ApplyTemplate",
         must=["if (paidPeriodEndUtc is DateTime pe)"],
         why=_R233_WHY + "ฝ่ายค้าน B1: ฟรีถาวร/ค่าแทน → ซื้อ ปิดรอบด้วยวันหมดอายุของรอบที่จ่าย"),
    dict(file=_SUBSVC, method="PlanPreviewForQuoteAsync",
         must=["PlanPurchasePreview.IssuesTaxInvoice(", "NewCyclePrice: q.NewCyclePrice"],
         why=_R233_WHY + "ฝ่ายค้าน N2/N3: ราคาจริงของรอบใหม่ · ธง VAT ตัวเดียวกับตัวออกใบ"),
    dict(file=PLATFORM, method="IssuePaidReceiptAsync",
         must=["PlanPurchasePreview.IssuesTaxInvoice(settings.PlatformIsVatRegistered, settings.PlatformSellerTaxId)"],
         forbid=["settings.PlatformIsVatRegistered && IsValidTaxId("],
         why=_R233_WHY + "ฝ่ายค้าน N3: ออกใบกำกับไหม = ตัวตัดสินเดียวกับ preview"),
    dict(file=_R232_CHECKOUT, method="CreateOrderAsync",
         must=["PublicCheckoutPolicy.MustRequote(", "_subs.QuotePlanChangeAsync("],
         before=[("PublicCheckoutPolicy.MustRequote(", "_subs.ConvertTrialAsync(")],
         why=_R233_WHY + "ฝ่ายค้าน S5 (K-6): resume รายการส่วนต่างเก่า ⇒ คิดยอดใหม่ ณ เวลา resume (ไม่ตรง + ยังไม่เริ่มชำระ ⇒ ออกใหม่ผ่านเส้นเดิมที่ยกเลิกใบเก่า)"),
    dict(file=_R232_CHECKOUT, method="QuoteAsync",
         must=["RefusalPreviewAsync(", "RenewalPreviewAsync(", "q.Preview", "PlanPurchasePreview.ForAnonymous("],
         forbid=["throw new BusinessRuleException(decision.Refusal", ".AddMonths(", "PlatformPlanPricing.PeriodStart("],
         why=_R233_WHY + "233-3 ปฏิเสธ = ใบเสนอพร้อมเหตุ+วันที่+ทางไปต่อ (ไม่ใช่ error ลอย) · ต่ออายุแสดงวันหมดอายุใหม่"),
    dict(file=_R232_CHECKOUT, method="CreateOrderAsync",
         must=["RefusalPreviewAsync("],
         forbid=["throw new BusinessRuleException(decision.Refusal ?? PublicCheckoutPolicy.DowngradeRefusal"],
         why=_R233_WHY + "ข้อความปฏิเสธตอนสร้างรายการ = ข้อความเดียวกับกล่องสรุป"),
    dict(file=_R232_CHECKOUT, method="RenewalPreviewAsync",
         must=["PlanPurchasePreview.ForPurchase("], forbid=[".AddMonths("],
         why=_R233_WHY + "233-1 ต่ออายุ = max(วันหมดอายุเดิม, วันชำระ) + รอบ ผ่าน PaidPeriod ตัวเดียว"),
    dict(file=_R232_CHECKOUT, method="OwnedCompaniesAsync",
         must=["PlanPurchasePreview.LowerPlanNote(", "PlatformPlanPricing.Classify(", "PlatformPlanPricing.ChangeKind.Downgrade", "SubscriptionStatus.Active", "IsPermanentFree"],
         why=_R233_WHY + "pricing.html ป้าย 'ต่ำกว่าแพ็กปัจจุบัน' = เงื่อนไขเดียวกับ DecideOrder (ตัดสินที่เซิร์ฟเวอร์ · เฉพาะบริษัทที่ผู้ใช้เป็นเจ้าของ)"),
    dict(file=PLATFORM, method="IssuePaidReceiptAsync",
         must=["PlanPurchasePreview.InvoiceDiscountGross(payment.CouponDiscountAmount, payment.IsCycleChange, payment.CycleChangeCredit)"],
         why=_R233_WHY + "233-4 เครดิตรอบเดิมของการเปลี่ยนรอบเป็นส่วนลดของบรรทัดก่อน VAT (§86/4) เหมือนคูปอง"),
]

# รอบ 234 (คำตัดสิน 234-1…234-6 · 234-W1…W5): หัก ณ ที่จ่ายอัตโนมัติ + ด่านข้อมูลบริษัทก่อนชำระ + 50 ทวิ จากลูกค้า → ทะเบียนภาษีถูกหัก —
# ทุกเส้นที่ผู้เช่าจ่ายเงินให้ NextAcc เรียกตัวตัดสินเดียว (PlatformWithholdingReader → PlatformWhtSuggestion/PlatformPayerProfileGate) · ห้ามคิดยอดหักเอง
